<script lang="ts">
 import type {BudgetEngine} from '$lib/server/budgetEngine/service';
 import type {Category} from '$lib/types';import {formatMoney,formatDate} from '$lib/utils';
 import FundingAmount from './FundingAmount.svelte';
 import Badge from './FinancialBadge.svelte';import CategoryPill from './CategoryPill.svelte';
 let {funding,fundingDate,commandKey,categories}:{funding:ReturnType<BudgetEngine['dashboard']>;fundingDate:string;commandKey:string;categories:Category[]}=$props();
 const monthLabel=$derived(new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${fundingDate}T12:00:00Z`)));
 const known=$derived(funding.view.coverageComplete&&funding.view.ledger!==null);
 const rows=$derived(funding.categoryStates.filter(s=>categories.some(c=>c.id===s.categoryId&&c.type!=='income'&&!categories.some(child=>child.parent_id===c.id))));
 const targetLabel={unknown:'Target progress unknown',no_target:'No target',met:'Target met',needs_funding:'Needs more funding'};

</script>
<section class="product-panel" aria-label="Cash allocations">
 <header class="product-panel-header"><div><h2>Cash allocations</h2><p class="product-row-caption">{monthLabel} · target progress and cash are separate</p></div><Badge value={known?formatMoney(funding.view.ledger!.readyToAssignCents):undefined} label={known?'Ready to assign':'Available cash unknown'} tone={known?(funding.view.ledger!.readyToAssignCents<0?'negative':'neutral'):'attention'}/></header>
 {#if !known}<div class="product-panel-body"><p>{!funding.view.baseline?'Funding needs an accepted end-of-day balance baseline. Your existing targets and records are preserved.':'Posted activity coverage needs review or refresh before funding can be shown.'}</p></div>{/if}
 {#if funding.view.baseline}<div class="product-panel-body"><form method="POST" action={`?/refresh&month=${fundingDate.slice(0,7)}`} data-budget-command="refresh"><input type="hidden" name="revision" value={funding.view.revision}/><input type="hidden" name="key" value={`${commandKey}:refresh`}/><button class="product-button">Refresh posted activity</button></form><p class="product-row-caption">Refresh rebuilds derived budget activity, not bank transactions. Unresolved transfers or categories need review.</p></div>{/if}
 {#if known&&funding.view.ledger!.cashBackingShortfallCents>0}<div role="status" class="product-attention"><Badge value={formatMoney(funding.view.ledger!.cashBackingShortfallCents)} label="Cash backing shortfall" tone="attention"/><span>Cover overspending before making new allocations.</span></div>{/if}
 <ul class="product-list">{#each rows as s(s.categoryId)}{@const c=categories.find(c=>c.id===s.categoryId)!}<li class="funding-row" id={`funding-category-${s.categoryId}`}><div class="product-row"><div class="product-row-main"><a href={`/categories/${s.categoryId}?date_from=${fundingDate.slice(0,7)}-01&date_to=${fundingDate}&funding_month=${fundingDate.slice(0,7)}`}><CategoryPill id={c.id} name={c.name} color={c.color}/></a><span class="product-row-caption">{targetLabel[s.targetStatus]}{#if s.neededThisMonthCents!==null&&s.neededThisMonthCents>0} · {formatMoney(s.neededThisMonthCents)} needed{/if}</span>{#if s.assignedCents!==null}<span class="product-row-caption">Assigned this month {formatMoney(s.assignedCents)}</span>{/if}</div><FundingAmount state={s}/></div>
 {#if known}<form method="POST" action={`?/allocate&month=${fundingDate.slice(0,7)}`} data-budget-command="allocate" class="allocation-form"><input type="hidden" name="category_id" value={s.categoryId}/><input type="hidden" name="revision" value={funding.view.revision}/><input type="hidden" name="key" value={`${commandKey}:${s.categoryId}`}/><label>Assign (+) or return (−)<input name="amount" inputmode="decimal" placeholder="0.00" required aria-label={`Assignment for ${c.name}`}/></label><label>Effective date<input name="date" type="date" value={fundingDate} min={`${fundingDate.slice(0,7)}-01`} max={fundingDate} required/></label><button class="product-button primary">Apply</button></form>{/if}</li>{/each}</ul>
 <footer class="product-details">{#if funding.view.baseline}<p>Accepted balance baseline {formatDate(funding.view.baseline.asOfDate)}{#if funding.view.activityThrough} · activity checked through {formatDate(funding.view.activityThrough)}{/if}.</p>{/if}These are budget allocations, not payments. Target met does not mean cash remains after spending. Unknown coverage is never treated as zero.</footer>
</section>
<style>.funding-row+.funding-row{border-top:1px solid var(--border)}.allocation-form{display:flex;flex-wrap:wrap;gap:12px;align-items:end;padding:0 22px 18px}.allocation-form label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--muted-foreground);flex:1;min-width:130px}.allocation-form input{width:100%;min-height:44px;padding:8px 10px;border:1px solid var(--input);border-radius:var(--radius);background:var(--surface);color:var(--foreground)}.allocation-form button{min-height:44px}</style>
